// The form fields arrive under body, the file as a binary property. Which key
// that file lands under depends on the n8n version - 'video', 'video0', or the
// multipart field name - so it is found rather than assumed, and when nothing
// arrives the error names the keys that did, which is what you need to see.
const item = $input.first();
const body = item.json.body || item.json;
const binary = item.binary || {};
const keys = Object.keys(binary);

const key = keys.find((name) => String(binary[name].mimeType || '').startsWith('video/')) || keys[0];
if (!key) {
  throw new Error('영상 파일이 없습니다. 받은 바이너리 키: ' + JSON.stringify(keys));
}
const file = binary[key];

const title = String(body.title || '').trim();
if (!title) {
  throw new Error('제목이 비어 있습니다.');
}

return [{
  json: {
    story: String(body.story || 'unknown'),
    label: String(body.label || ''),
    reason: String(body.reason || ''),
    title: title.slice(0, 95),
    description: String(body.description || '').slice(0, 4900),
    tags: String(body.tags || '주식,AI주식,모의투자,코스피,투자기록'),
    privacyStatus: ['private', 'unlisted', 'public'].includes(String(body.privacyStatus)) ? String(body.privacyStatus) : 'private',
    receivedAs: key,
    size: String(file.fileSize || ''),
  },
  // handed on as 'data', which is the binary field every n8n node reads by default
  binary: { data: file },
}];

